package com.justbash.interpreter.expansion

fun applyPatternRemoval(ctx: ExpansionContext, value: String, regexStr: String, side: String, greedy: Boolean): String { if (side == "prefix") { ctx.executionScope.consumeLimited("pattern-removal", Math.max(1, value.length).toLong(), ctx.limits.maxGlobOperations, "pattern removal"); val pattern = try { Regex("^$regexStr", setOf(RegexOption.DOT_MATCHES_ALL)) } catch (e: Exception) { return value }; return pattern.replaceFirst(value, "") }; val regex = try { Regex("$regexStr\$", setOf(RegexOption.DOT_MATCHES_ALL)) } catch (e: Exception) { return value }; if (greedy) { ctx.executionScope.consumeLimited("pattern-removal", Math.max(1, value.length).toLong(), ctx.limits.maxGlobOperations, "pattern removal"); return regex.replaceFirst(value, "") }; ctx.executionScope.consumeLimited("pattern-removal", Math.max(1, value.length).toLong(), ctx.limits.maxGlobOperations, "pattern removal"); val shortest = Regex("^(?:.*)($regexStr)\$", setOf(RegexOption.DOT_MATCHES_ALL)).find(value) ?: return value; val suffix = shortest.groupValues[1]; return value.substring(0, value.length - suffix.length) }
fun getVarNamesWithPrefix(ctx: ExpansionContext, prefix: String): List<String> { val matching = LinkedHashSet<String>(); for (name in ctx.state.env.keys) { if (name.startsWith(prefix)) matching.add(name) }; for (name in ctx.state.arrays.keys) { if (name.startsWith(prefix)) matching.add(name) }; return matching.sorted() }
